(()=>{'use strict';function prepare(el){if(el.dataset.preparing)return;el.dataset.preparing='1';const src=el.dataset.printSrc,im=new Image();im.decoding='async';im.onload=()=>{el.style.setProperty('--art-texture',`url("${src}")`);el.classList.add('texture-ready');const b=el.closest('button[data-image]');if(b)b.dataset.image=src;if(el.dataset.backSrc)el.style.setProperty('--back-texture',`url("${el.dataset.backSrc}")`)};im.onerror=()=>{delete el.dataset.preparing};im.src=src}const nodes=[...document.querySelectorAll('[data-print-src]')];const observer=typeof IntersectionObserver==='function'?new IntersectionObserver(es=>es.forEach(e=>{if(e.isIntersecting&&!e.target.closest('.showroom-slide:not(.active):not(.after)')){prepare(e.target);observer.unobserve(e.target)}}),{rootMargin:'250px'}):null;nodes.forEach(el=>observer?observer.observe(el):prepare(el));function current(root){if(root.getBoundingClientRect().top>innerHeight+250)return;root.querySelectorAll('.showroom-slide.active [data-print-src],.showroom-slide.after [data-print-src]').forEach(prepare)}document.querySelectorAll('.showroom').forEach(current);document.addEventListener('pa:showroom',e=>current(e.detail.root));})();